(()=>{const q=document.querySelector('#money-search-q'),status=document.querySelector('#money-search-status'),out=document.querySelector('#money-search-results');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let rows=[];function render(){const term=q.value.trim().toLowerCase(),list=(term?rows.filter(x=>x.search.includes(term)):rows.slice(0,60)).slice(0,120);status.textContent='Showing '+list.length+' results. Refine the search for narrower evidence routes.';out.innerHTML=list.map(x=>'<article class="money-card"><span class="evidence-chip">'+esc(x.evidenceClass)+'</span><h3>'+esc(x.name)+'</h3><p>'+esc(x.categoryTitle)+' · '+esc(x.value||x.status)+'</p><p class="money-source-boundary">'+esc(x.notEstablished)+'</p><a class="btn" href="'+esc(x.route)+'">Open category</a> <a class="btn alt" href="'+esc(x.sourceUrl)+'">Source</a></article>').join('')}fetch('data/money-search-index.json').then(r=>r.json()).then(d=>{rows=d.records||[];render()});q.addEventListener('input',render)})();